package tw.radar.shortscan;
import android.app.*;import android.content.*;import android.content.pm.*;import android.net.Uri;import android.os.*;import android.provider.Settings;import android.widget.*;import java.io.*;import java.security.MessageDigest;import java.util.*;import java.util.concurrent.TimeUnit;import java.util.regex.*;import org.json.*;import okhttp3.*;
public class UpdateActivity extends Activity {
 private static final String BASE="https://github.com/rex0966445518/stock-monitor-updates/releases/download/",API="https://api.github.com/repos/rex0966445518/stock-monitor-updates/releases?per_page=100";
 private static final Pattern TAG=Pattern.compile("^short-radar-v(\\d{1,5}\\.\\d{1,5}\\.\\d{1,5})(?:-test)?$");
 private final OkHttpClient http=new OkHttpClient.Builder().callTimeout(120,TimeUnit.SECONDS).build();private TextView status;private Button check,install;private String version,remote,url,digest;private long size;private boolean pending=false;private volatile boolean closed=false;
 @Override public void onCreate(Bundle b){super.onCreate(b);try{version=getPackageManager().getPackageInfo(getPackageName(),0).versionName;}catch(Exception e){version="0.3.2";}ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(Ui.BG);LinearLayout root=Ui.col(this);int p=Ui.dp(this,16);root.setPadding(p,p,p,p);scroll.addView(root);setContentView(scroll);Ui.add(root,Ui.text(this,"GitHub 一鍵更新",25,Ui.MINT,true));Ui.add(root,Ui.text(this,"目前安裝版本 v"+version,17,Ui.FG,true));Ui.add(root,Ui.text(this,"只檢查盤中做空雷達獨立發布。下載後核對 SHA-256、套件名、版本及發行憑證；Android 仍需本人確認安裝。",13,Ui.MUTED,false));status=Ui.text(this,"尚未檢查",15,Ui.FG,false);Ui.add(root,status);check=Ui.button(this,"檢查 GitHub 最新版本");check.setOnClickListener(v->search());Ui.add(root,check);install=Ui.button(this,"下載並安裝更新");install.setEnabled(false);install.setOnClickListener(v->download());Ui.add(root,install);Button page=Ui.button(this,"開啟 GitHub 發布頁");page.setOnClickListener(v->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://github.com/rex0966445518/stock-monitor-updates/releases"))));Ui.add(root,page);Button back=Ui.button(this,"返回首頁");back.setOnClickListener(v->finish());Ui.add(root,back);}
 private void ui(String s,boolean b){runOnUiThread(()->{if(closed)return;status.setText(s);check.setEnabled(true);install.setEnabled(b);});}
 static int cmp(String a,String b){String[] x=a.split("\\."),y=b.split("\\.");for(int i=0;i<3;i++){int c=Integer.compare(Integer.parseInt(x[i]),Integer.parseInt(y[i]));if(c!=0)return c;}return 0;}
 private void search(){check.setEnabled(false);install.setEnabled(false);status.setText("正在檢查 GitHub 發布…");new Thread(()->{try(Response r=http.newCall(new Request.Builder().url(API).header("Accept","application/vnd.github+json").build()).execute()){if(!r.isSuccessful())throw new IOException("HTTP "+r.code());JSONArray releases=new JSONArray(r.body().string());String best=version,bestUrl=null,bestDigest=null;long bestSize=0;boolean hasNew=false;for(int i=0;i<releases.length();i++){JSONObject rel=releases.getJSONObject(i);if(rel.optBoolean("draft"))continue;String tag=rel.optString("tag_name");Matcher m=TAG.matcher(tag);if(!m.matches())continue;String ver=m.group(1);if(cmp(ver,version)<=0)continue;hasNew=true;if(cmp(ver,best)<=0)continue;JSONArray assets=rel.optJSONArray("assets");if(assets==null)continue;for(int j=0;j<assets.length();j++){JSONObject a=assets.getJSONObject(j);String n=a.optString("name"),u=a.optString("browser_download_url"),d=a.optString("digest");long s=a.optLong("size");if(!n.equals("ShortRadar-v"+ver+".apk")||!u.equals(BASE+tag+"/"+n)||!d.matches("sha256:[a-fA-F0-9]{64}")||s<=0||s>100_000_000L||!"uploaded".equals(a.optString("state")))continue;best=ver;bestUrl=u;bestDigest=d.substring(7);bestSize=s;break;}}if(bestUrl==null){ui(hasNew?"有新版發布，但找不到符合安全規格的安裝檔；請查看官方發布頁。":"目前沒有更新版本。",false);return;}remote=best;url=bestUrl;digest=bestDigest;size=bestSize;ui("找到新版本 v"+remote+"\n大小 "+size+" bytes\n按下方按鈕即可下載並驗證。",true);}catch(Exception e){ui("無法檢查更新："+e.getMessage(),false);}}).start();}
 private File apk(){return new File(getCacheDir(),"radar-update.apk");}
 @SuppressWarnings("deprecation") private Set<String> certs(PackageInfo p)throws Exception{Signature[] sig=Build.VERSION.SDK_INT>=28?(p.signingInfo==null?null:p.signingInfo.getApkContentsSigners()):p.signatures;if(sig==null||sig.length==0)throw new Exception("APK 無簽章資訊");Set<String> set=new HashSet<>();for(Signature s:sig)set.add(hex(MessageDigest.getInstance("SHA-256").digest(s.toByteArray())));return set;}
 private static String hex(byte[] data){StringBuilder b=new StringBuilder();for(byte x:data)b.append(String.format(Locale.ROOT,"%02x",x&255));return b.toString();}
 @SuppressWarnings("deprecation") private void verifyPackage(File f)throws Exception{PackageManager pm=getPackageManager();int flags=Build.VERSION.SDK_INT>=28?PackageManager.GET_SIGNING_CERTIFICATES:PackageManager.GET_SIGNATURES;PackageInfo incoming=pm.getPackageArchiveInfo(f.getPath(),flags),local=pm.getPackageInfo(getPackageName(),flags);if(incoming==null||!getPackageName().equals(incoming.packageName)||!remote.equals(incoming.versionName))throw new Exception("APK 套件或版本不相符");long nv=Build.VERSION.SDK_INT>=28?incoming.getLongVersionCode():incoming.versionCode,ov=Build.VERSION.SDK_INT>=28?local.getLongVersionCode():local.versionCode;if(nv<=ov)throw new Exception("禁止降版或重裝同一版本");if(!certs(local).equals(certs(incoming)))throw new Exception("發行簽章不同，無法覆蓋更新。請勿卸載，先備份設定並確認固定簽章遷移。");}
 private void download(){if(url==null)return;check.setEnabled(false);install.setEnabled(false);status.setText("正在下載及驗證 APK…");new Thread(()->{File f=apk();File temp=new File(getCacheDir(),"radar-update.part");try{MessageDigest sha=MessageDigest.getInstance("SHA-256");long count=0;try(Response r=http.newCall(new Request.Builder().url(url).build()).execute()){if(!r.isSuccessful())throw new IOException("HTTP "+r.code());try(InputStream in=r.body().byteStream();FileOutputStream out=new FileOutputStream(temp)){byte[] buf=new byte[32768];int n;while((n=in.read(buf))!=-1){count+=n;if(count>size)throw new IOException("檔案大小異常");sha.update(buf,0,n);out.write(buf,0,n);}}}if(count!=size||!hex(sha.digest()).equalsIgnoreCase(digest))throw new Exception("SHA-256 驗證失敗");verifyPackage(temp);if(f.exists()&&!f.delete())throw new IOException("無法清理舊檔");if(!temp.renameTo(f))throw new IOException("無法保存 APK");runOnUiThread(()->{if(closed)return;pending=true;launchInstaller();});}catch(Exception e){temp.delete();ui("更新已阻擋："+e.getMessage(),false);}}).start();}
 private void launchInstaller(){if(!pending||!apk().isFile())return;if(!getPackageManager().canRequestPackageInstalls()){status.setText("已驗證 APK。請允許此 App 安裝未知來源應用程式，返回後會啟動安裝畫面。");try{startActivityForResult(new Intent(Settings.ACTION_MANAGE_UNKNOWN_APP_SOURCES,Uri.parse("package:"+getPackageName())),77);}catch(Exception e){ui("請在系統設定授權安裝未知來源。",true);}return;}try{verifyPackage(apk());Intent i=new Intent(Intent.ACTION_VIEW);i.setDataAndType(Uri.parse("content://tw.radar.shortscan.updates/radar-update.apk"),"application/vnd.android.package-archive");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(i);pending=false;ui("已開啟 Android 安裝畫面，請確認更新。",true);}catch(Exception e){ui("無法啟動安裝："+e.getMessage(),false);}}
 @Override protected void onActivityResult(int r,int c,Intent data){super.onActivityResult(r,c,data);if(r==77&&pending){if(getPackageManager().canRequestPackageInstalls())launchInstaller();else ui("未授權安裝，已取消。",true);}}
 @Override protected void onDestroy(){closed=true;super.onDestroy();}
}